/* global Office, console, window */

// v1.0.6b: 診断強化版。
// 決定的に知りたいこと:
//   (1) イベントランタイムで Office.onReady が発火するか?(= ホストが配送する前提)
//   (2) ホスト名 / プラットフォーム / 要件セット対応状況
//   (3) 例外・未処理 rejection が起きていないか
//   (4) ログがいつ出るか(タイムスタンプ。起動時=long / 送信時=short の判別)
// JS のみの変更なので admin 再consent 不要・GitHub Pages 即反映。
const BUILD_TAG = "v1.0.7-runtime-reqs-2026-06-09";

console.log(`[PauseMan] === module eval start ${BUILD_TAG} @ ${new Date().toISOString()} ===`);
console.log(`[PauseMan] typeof Office=${typeof Office}; Office.actions=${typeof (typeof Office !== "undefined" && (Office as any).actions)}`);

if (typeof window !== "undefined") {
  window.addEventListener("error", (ev: any) => {
    console.log(`[PauseMan] window 'error' @ ${new Date().toISOString()}: ${ev && ev.message}`);
    console.log(`[PauseMan]   at ${ev && ev.filename}:${ev && ev.lineno}:${ev && ev.colno}`);
    console.log(`[PauseMan]   STACK: ${ev && ev.error && ev.error.stack}`);
  });
  window.addEventListener("unhandledrejection", (ev: any) => {
    const r = ev && ev.reason;
    console.log(`[PauseMan] unhandledrejection @ ${new Date().toISOString()}: ${r && r.message ? r.message : r}`);
    console.log(`[PauseMan]   STACK: ${r && r.stack}`);
  });
}

function onMessageSendHandler(event: Office.AddinCommands.Event) {
  console.log(`[PauseMan] *** handler ENTERED *** ${BUILD_TAG} @ ${new Date().toISOString()}`);
  event.completed({
    allowEvent: false,
    errorMessage: `${BUILD_TAG}\n\n✅ ハンドラが実行されました (${new Date().toISOString()})。`,
  } as any);
  console.log(`[PauseMan] event.completed() called ${BUILD_TAG}`);
}

// --- 関連付け: トップレベルで無条件 ---
try {
  Office.actions.associate("onMessageSendHandler", onMessageSendHandler);
  console.log(`[PauseMan] associate() OK at top level ${BUILD_TAG}`);
} catch (e) {
  console.log(`[PauseMan] associate() THREW: ${e} ${BUILD_TAG}`);
}

// --- (1) Office が ready になるか? これが本命の観測点 ---
Office.onReady((info: any) => {
  console.log(`[PauseMan] *** Office.onReady FIRED *** host=${info && info.host} platform=${info && info.platform} ${BUILD_TAG} @ ${new Date().toISOString()}`);
  try {
    const ctx: any = (Office as any).context;
    const diag = ctx && ctx.mailbox && ctx.mailbox.diagnostics;
    console.log(`[PauseMan] diagnostics hostName=${diag && diag.hostName} hostVersion=${diag && diag.hostVersion} OWAView=${diag && diag.OWAView}`);
    const req = ctx && ctx.requirements;
    if (req && req.isSetSupported) {
      console.log(`[PauseMan] Mailbox isSetSupported 1.12=${req.isSetSupported("Mailbox", "1.12")} 1.13=${req.isSetSupported("Mailbox", "1.13")} 1.14=${req.isSetSupported("Mailbox", "1.14")} 1.15=${req.isSetSupported("Mailbox", "1.15")}`);
    }
  } catch (e) {
    console.log(`[PauseMan] diag read error: ${e}`);
  }
});
